/**
 * The home page module: the finder's typer. It reads the theme list the finder
 * writes on its link (data-explorer-themes), then types each phrase phrases()
 * finds there, holds it, deletes it and moves on, the link always searching
 * /themes for the phrase on screen. Reduced motion holds the first phrase.
 */
const MAX_PHRASES = 6;
const TYPE_STEP = 75;
const ERASE_STEP = 36;
const PHRASE_HOLD = 1900;
const GAP_HOLD = 320;
const PLAIN_WORD = /^[a-z]+$/;

/**
 * The typer's phrases: per theme, in order, the first of its tags that is one
 * plain word its niche also uses, never twice. Every phrase is a tag of the
 * theme it came from, so a search for it finds at least that theme.
 * @param {{ niche: string, tags: string[] }[]} themes - the themes the finder lists
 * @returns {string[]}
 */
export function phrases(themes) {
  const found = new Set();

  for (const theme of themes) {
    const subject = theme.tags.find((tag) => PLAIN_WORD.test(tag) && new RegExp(`\\b${tag}\\b`, 'i').test(theme.niche));

    if (subject) {
      found.add(subject);
    }
  }

  return [...found].slice(0, MAX_PHRASES);
}

export default async () => {
  const $link = document.querySelector('[data-explorer-typer]');

  // The finder draws no typer when the build has no theme to search for
  if (!$link) {
    return;
  }

  const $word = $link.querySelector('[data-explorer-typer-word]');
  const list = phrases(JSON.parse($link.dataset.explorerThemes));
  const still = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  let index = 0;

  if (!list.length) {
    return;
  }

  const aim = () => {
    $link.href = `/themes?q=${encodeURIComponent(list[index])}`;
    $link.setAttribute('aria-label', `${$link.dataset.searchLabel} ${list[index]}`);
  };

  const type = (length) => {
    $word.textContent = list[index].slice(0, length);

    if (length < list[index].length) {
      setTimeout(type, TYPE_STEP, length + 1);
      return;
    }

    setTimeout(erase, PHRASE_HOLD, length);
  };

  const erase = (length) => {
    $word.textContent = list[index].slice(0, length);

    if (length > 0) {
      setTimeout(erase, ERASE_STEP, length - 1);
      return;
    }

    index = (index + 1) % list.length;
    aim();
    setTimeout(type, GAP_HOLD, 1);
  };

  aim();
  $word.textContent = list[index];

  if (!still) {
    setTimeout(erase, PHRASE_HOLD, list[index].length);
  }
};
